    match std::fs::read_to_string(&readme) {
        Ok(_) => println!("{}: read OK", label),
        Err(e) => println!("{}: read ERR: {}", label, e),
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    probe(&args[1], &args[2]);
}
