/// raw size of a sha1 object id
pub const GIT_OID_RAWSZ: usize = 20;

#[repr(C)]
#[derive(Clone, Copy, PartialEq, Eq)]
pub struct GitOid {
    pub id: [u8; GIT_OID_RAWSZ],
}

impl GitOid {
    pub fn zeroed() -> GitOid {
        GitOid { id: [0u8; GIT_OID_RAWSZ] }
    }
    pub fn is_zero(&self) -> bool {
        self.id.iter().all(|b| *b == 0)
    }
    pub fn to_hex(&self) -> String {
        let mut s = String::with_capacity(GIT_OID_RAWSZ * 2);
        for b in self.id.iter() {
            s.push_str(&format!("{:02x}", b));
        }
        s
    }
}

