pub enum ErrorClass {
    None = 0,
    NoMemory = 1,
    Os = 2,
    Invalid = 3,
    Reference = 4,
    Zlib = 5,
    Repository = 6,
    Config = 7,
    Regex = 8,
    Odb = 9,
    Index = 10,
    Object = 11,
    Net = 12,
    Tag = 13,
    Tree = 14,
    Indexer = 15,
    Ssl = 16,
    Submodule = 17,
    Thread = 18,
    Stash = 19,
    Checkout = 20,
    Fetchhead = 21,
    Merge = 22,
    Ssh = 23,
    Filter = 24,
    Revert = 25,
    Callback = 26,
    Cherrypick = 27,
    Describe = 28,
    Rebase = 29,
    Filesystem = 30,
    Patch = 31,
    Worktree = 32,
    Sha1 = 33,
    Http = 34,
    Internal = 35,
