    NotFound,
    Exists,
    Ambiguous,
    BufSize,
    User,
    BareRepo,
    UnbornBranch,
    Unmerged,
    NotFastForward,
    InvalidSpec,
    Conflict,
    Locked,
    Modified,
    Auth,
    Certificate,
    Applied,
    Peel,
    Eof,
    Invalid,
    Uncommitted,
    MergeConflict,
    HashsumMismatch,
    IndexDirty,
    ApplyFail,
    Owner,
    Timeout,
}

impl ErrorCode {
    pub fn from_code(code: c_int) -> ErrorCode {
        match code {
            GIT_OK | GIT_ERROR => ErrorCode::GenericError,
            -3 => ErrorCode::NotFound,
            -4 => ErrorCode::Exists,
            -5 => ErrorCode::Ambiguous,
            -6 => ErrorCode::BufSize,
            -7 => ErrorCode::User,
            -8 => ErrorCode::BareRepo,
