/// An error, either coming from libgit2, the filesystem or the program itself.
#[derive(Debug)]
pub enum EurekaError {
    Git { message: String, klass: c_int, code: c_int },
    Io(std::io::Error),
    Message(String),
}

impl std::fmt::Display for EurekaError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            EurekaError::Git { message, klass, code } => {
                write!(f, "{}", message)?;
                if *klass != 0 {
                    write!(f, "; class={} ({})", ErrorClass::from_raw(*klass).name(), klass)?;
                }
                if let Some(name) = ErrorCode::from_code(*code).name() {
                    write!(f, "; code={} ({})", name, code)?;
                }
                Ok(())
            }
            EurekaError::Io(e) => write!(f, "{}", e),
            EurekaError::Message(m) => write!(f, "{}", m),
        }
    }
}

impl From<std::io::Error> for EurekaError {
    fn from(e: std::io::Error) -> EurekaError {
        EurekaError::Io(e)
    }
}

pub fn last_error(code: c_int) -> EurekaError {
    unsafe {
        let ptr = git_error_last();
        if ptr.is_null() {
            return EurekaError::Git {
                message: "an unknown git error occurred".to_string(),
                klass: 0,
                code,
            };
        }
        let e = *ptr;
        let msg = if e.message.is_null() {
            String::new()
        } else {
            CStr::from_ptr(e.message).to_string_lossy().into_owned()
        };
        git_error_clear();
        EurekaError::Git { message: msg, klass: e.klass, code }
    }
}

pub fn str_error<S: Into<String>>(s: S) -> EurekaError {
    EurekaError::Message(s.into())
}

pub type Result<T> = std::result::Result<T, EurekaError>;

pub fn cstr_of(s: &str) -> Result<std::ffi::CString> {
    std::ffi::CString::new(s.as_bytes()).map_err(|_| str_error("data contained a nul byte that could not be represented as a string"))
}

pub fn cbytes(path: &Path) -> Vec<u8> {
    use std::os::unix::ffi::OsStrExt;
    path.as_os_str().as_bytes().to_vec()
}

/// A thin wrapper around a `git_repository*`.
pub struct Repository {
    raw: *mut git_repository,
    path: PathBuf,
}

impl Repository {
    pub fn open(path: &Path) -> Result<Repository> {
        crate::init();
        let cs = std::ffi::CString::new(cbytes(path)).unwrap_or_default();
        let mut raw: *mut git_repository = std::ptr::null_mut();
        let rc = unsafe { git_repository_open(&mut raw, cs.as_ptr()) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Repository { raw, path: path.to_path_buf() })
    }

    pub fn raw(&self) -> *mut git_repository {
        self.raw
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    pub fn workdir(&self) -> Option<&Path> {
        unsafe {
            let p = git_repository_workdir(self.raw);
            if p.is_null() {
                return None;
            }
            let s = CStr::from_ptr(p).to_bytes();
            Some(Path::new(std::str::from_utf8(s).unwrap_or("")))
        }
    }

    /// Look up a reference by name, optionally resolving symbolic references.
    pub fn reference_lookup(&self, name: &str, resolve: bool) -> Result<Reference> {
        let cs = cstr_of(name)?;
        let mut raw: *mut git_reference = std::ptr::null_mut();
        let rc = if resolve {
            unsafe { git_reference_lookup_resolved(&mut raw, self.raw, cs.as_ptr(), -1) }
        } else {
            unsafe { git_reference_lookup(&mut raw, self.raw, cs.as_ptr()) }
        };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Reference { raw, repo: self.raw() })
    }

    pub fn branch_lookup(&self, name: &str, remote: bool) -> Result<Reference> {
        let cs = cstr_of(name)?;
        let mut raw: *mut git_reference = std::ptr::null_mut();
        let rc = unsafe { git_branch_lookup(&mut raw, self.raw, cs.as_ptr(), if remote { 1 } else { 0 }) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Reference { raw, repo: self.raw() })
    }

    /// Create (or move) a branch pointing at `id`.
    pub fn branch_create(&self, name: &str, id: &GitOid, force: bool) -> Result<()> {
        let cs = cstr_of(name)?;
        let log = cstr_of(&format!("branch: Created from {}", id.to_hex()))?;
        let mut raw: *mut git_reference = std::ptr::null_mut();
        let rc = unsafe {
            git_reference_create(&mut raw, self.raw, cs.as_ptr(), id as *const GitOid, force as c_int, log.as_ptr())
        };
        if rc < 0 {
            return Err(last_error(rc));
        }
        unsafe {
            git_reference_free(raw);
        }
        Ok(())
    }

    pub fn set_head(&self, refname: &str) -> Result<()> {
        let cs = cstr_of(refname)?;
        let rc = unsafe { git_repository_set_head(self.raw, cs.as_ptr()) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(())
    }

    pub fn head_detached(&self) -> Result<bool> {
        let rc = unsafe { git_repository_head_detached(self.raw) };
        match rc {
            0 => Ok(false),
            1 => Ok(true),
            n => Err(last_error(n)),
        }
    }

    pub fn checkout_tree(&self, treeish: *const git_object, strategy: c_uint) -> Result<()> {
        let mut opts: GitCheckoutOptions = unsafe { std::mem::zeroed() };
        let rc = unsafe { git_checkout_init_options(&mut opts, GIT_CHECKOUT_OPTIONS_VERSION) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        opts.checkout_strategy = strategy;
        let rc = unsafe { git_checkout_tree(self.raw, treeish, &opts) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(())
    }

    pub fn config_string(&self, key: &str) -> Result<String> {
        let mut cfg: *mut git_config = std::ptr::null_mut();
        let rc = unsafe { git_repository_config(&mut cfg, self.raw) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        let cs = cstr_of(key)?;
        let mut out: *const c_char = std::ptr::null();
        let rc = unsafe { git_config_get_string(&mut out, cfg, cs.as_ptr()) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        unsafe {
            let s = CStr::from_ptr(out).to_bytes();
            Ok(String::from_utf8_lossy(s).into_owned())
        }
    }

    pub fn index(&self) -> Result<Index> {
        let mut raw: *mut git_index = std::ptr::null_mut();
        let rc = unsafe { git_repository_index(&mut raw, self.raw) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Index { raw, repo: self.raw() })
    }

    pub fn signature_now(&self, name: &str, email: &str) -> Result<Signature> {
        let n = cstr_of(name)?;
        let e = cstr_of(email)?;
        let mut raw: *mut git_signature = std::ptr::null_mut();
        let rc = unsafe { git_signature_now(&mut raw, n.as_ptr(), e.as_ptr()) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Signature { raw })
    }

    pub fn commit(
        &self,
        update_ref: Option<&str>,
        author: &Signature,
        committer: &Signature,
        message: &str,
        tree: *mut git_tree,
    ) -> Result<GitOid> {
        let update_ref = match update_ref {
            Some(s) => cstr_of(s)?,
            None => std::ffi::CString::new(Vec::<u8>::new()).unwrap(),
        };
        let msg = cstr_of(message)?;
        let mut parents: [*const git_commit; 0] = [];
        let mut id = GitOid::zeroed();
        let ur_ptr = if update_ref.as_bytes().is_empty() {
            std::ptr::null()
        } else {
            update_ref.as_ptr()
        };
        let rc = unsafe {
            git_commit_create(
                &mut id as *mut GitOid,
                self.raw,
                ur_ptr,
                author.raw,
                committer.raw,
                std::ptr::null(),
                msg.as_ptr(),
                tree,
                parents.as_mut_ptr(),
                0,
            )
        };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(id)
    }

    pub fn find_remote(&self, name: &str) -> Result<Remote> {
        let cs = cstr_of(name)?;
        let mut raw: *mut git_remote = std::ptr::null_mut();
        let rc = unsafe { git_remote_lookup(&mut raw, self.raw, cs.as_ptr()) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Remote { raw })
    }
}

impl Drop for Repository {
    fn drop(&mut self) {
        unsafe {
            git_repository_free(self.raw);
        }
    }
}

pub struct Reference {
    raw: *mut git_reference,
    repo: *mut git_repository,
}

impl Reference {
    pub fn name(&self) -> String {
        unsafe {
            let p = git_reference_name(self.raw);
            if p.is_null() {
                return String::new();
            }
            CStr::from_ptr(p).to_string_lossy().into_owned()
        }
    }

    pub fn shorthand(&self) -> String {
        unsafe {
            let p = git_reference_shorthand(self.raw);
            if p.is_null() {
                return String::new();
            }
            CStr::from_ptr(p).to_string_lossy().into_owned()
        }
    }

    pub fn symbolic_target(&self) -> Option<String> {
        unsafe {
            if git_reference_type(self.raw) != GIT_REFERENCE_SYMBOLIC {
                return None;
            }
            let p = git_reference_symbolic_target(self.raw);
            if p.is_null() {
                return None;
            }
            Some(CStr::from_ptr(p).to_string_lossy().into_owned())
        }
    }

    pub fn target(&self) -> Option<GitOid> {
        unsafe {
            let p = git_reference_target(self.raw);
            if p.is_null() {
                return None;
            }
            Some(*p)
        }
    }

    pub fn r#type(&self) -> c_int {
        unsafe { git_reference_type(self.raw) }
    }

    /// Peel the reference down to a commit.
    pub fn peel_to_commit(&self) -> Result<Commit> {
        let mut obj: *mut git_object = std::ptr::null_mut();
        let rc = unsafe { git_reference_peel(&mut obj, self.raw, 3 /* GIT_OBJECT_COMMIT */) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        let id = unsafe { *git_commit_id(obj as *const git_commit) };
        let mut raw: *mut git_commit = std::ptr::null_mut();
        let rc = unsafe { git_commit_lookup(&mut raw, self.repo, &id as *const GitOid) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(Commit { raw, repo: self.repo, id })
    }
}

impl Drop for Reference {
    fn drop(&mut self) {
        unsafe {
            git_reference_free(self.raw);
        }
    }
}

