}

impl Remote {
    pub fn push(&mut self, refspecs: &[&str]) -> Result<()> {
        let mut cstrs: Vec<std::ffi::CString> = Vec::new();
        for r in refspecs {
            cstrs.push(cstr_of(r)?);
        }
        let mut ptrs: Vec<*const c_char> = cstrs.iter().map(|c| c.as_ptr()).collect();
        let arr = GitStrArray { strings: ptrs.as_mut_ptr() as *mut *mut c_char, count: ptrs.len() };
        let rc = unsafe { git_remote_push(self.raw, &arr as *const GitStrArray, std::ptr::null_mut()) };
        if rc < 0 {
            return Err(last_error(rc));
        }
        Ok(())
    }
}

