        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    passwd_home()
}

#[repr(C)]
struct Passwd {
    pw_name: *const i8,
    pw_passwd: *const i8,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *const i8,
    pw_gecos2: *const i8,
    pw_dir: *const i8,
    pw_shell: *const i8,
}

extern "C" {
    fn getuid() -> u32;
    fn getpwuid_r(
        uid: u32,
        pwd: *mut Passwd,
        buf: *mut i8,
        buflen: usize,
        result: *mut *mut Passwd,
    ) -> i32;
    fn sysconf(name: i32) -> i64;
}

const _SC_GETPW_R_SIZE_MAX: i32 = 201;

/// Look the current user up in /etc/passwd to find their home directory.
fn passwd_home() -> Option<PathBuf> {
    let amount = unsafe { sysconf(_SC_GETPW_R_SIZE_MAX) };
    let amt = if amount < 0 { 512usize } else { amount as usize };
    let mut buf: Vec<i8> = Vec::with_capacity(amt);
    let mut pwd: Passwd = unsafe { std::mem::zeroed() };
    let mut result: *mut Passwd = std::ptr::null_mut();
    let uid = unsafe { getuid() };
    let rc = unsafe { getpwuid_r(uid, &mut pwd, buf.as_mut_ptr(), amt, &mut result) };
    if rc != 0 || result.is_null() || pwd.pw_dir.is_null() {
        return None;
    }
    let dir = unsafe { std::ffi::CStr::from_ptr(pwd.pw_dir) };
    let s = dir.to_bytes();
    if s.is_empty() {
        return None;
    }
    Some(PathBuf::from(std::os::unix::OsStr::from_bytes(s)))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub repo: String,
}

impl Config {
    /// Read the configuration file.  Any failure (missing file, bad json,
    /// wrong types) results in `None`.
    pub fn load() -> Option<Config> {
        let path = config_file()?;
        let contents = std::fs::read_to_string(&path).ok()?;
        parse_config(&contents)
    }

    /// Store the configuration, creating the configuration directory first.
    pub fn save(&self) -> std::io::Result<()> {
        let dir = config_dir().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::NotFound, "no home directory")
        })?;
        std::fs::create_dir_all(&dir)?;
        let path = dir.join("config.json");
        std::fs::write(&path, json_for(&self.repo))
    }

    pub fn repo_path(&self) -> PathBuf {
        PathBuf::from(&self.repo)
    }
}

/// Serialize `{"repo": <path>}` exactly like the original tool does.
pub fn json_for(repo: &str) -> String {
    format!("{{\"repo\":{}}}", json_string(repo))
}

fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// A tiny json reader, good enough for the single-field configuration file.
fn parse_config(text: &str) -> Option<Config> {
    let mut lexer = Lexer::new(text);
    let value = lexer.parse_value()?;
    match value {
        Json::Object(fields) => {
            // duplicate keys make deserialization fail
            let mut repos: Vec<&Json> = fields.iter().filter(|(k, _)| *k == "repo").map(|(_, v)| v).collect();
            if repos.len() != 1 {
                return None;
            }
            match repos.pop()? {
                Json::String(s) => Some(Config { repo: s.clone() }),
                _ => None,
            }
        }
        _ => None,
    }
}

enum Json {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Lexer<'a> {
    chars: Vec<char>,
    idx: usize,
    _marker: std::marker::PhantomData<&'a ()>,
}

impl<'a> Lexer<'a> {
    fn new(text: &'a str) -> Lexer<'a> {
        Lexer { chars: text.chars().collect(), idx: 0, _marker: std::marker::PhantomData }
    }

    fn skip_ws(&mut self) {
        while self.idx < self.chars.len() && self.chars[self.idx].is_whitespace() {
            self.idx += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.idx).copied()
    }

    fn parse_value(&mut self) -> Option<Json> {
        self.skip_ws();
        match self.peek()? {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(Json::String),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Option<Json> {
        self.idx += 1;
        let mut fields: Vec<(String, Json)> = Vec::new();
        self.skip_ws();
        if self.peek()? == '}' {
            self.idx += 1;
            return Some(Json::Object(fields));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek()? != ':' {
                return None;
            }
            self.idx += 1;
            let value = self.parse_value()?;
            fields.push((key, value));
            self.skip_ws();
            match self.peek()? {
                ',' => {
                    self.idx += 1;
                }
                '}' => {
                    self.idx += 1;
                    return Some(Json::Object(fields));
                }
                _ => return None,
            }
        }
    }

    fn parse_array(&mut self) -> Option<Json> {
        self.idx += 1;
        let mut items: Vec<Json> = Vec::new();
        self.skip_ws();
        if self.peek()? == ']' {
            self.idx += 1;
            return Some(Json::Array(items));
        }
        loop {
            let v = self.parse_value()?;
            items.push(v);
            self.skip_ws();
            match self.peek()? {
                ',' => {
                    self.idx += 1;
                }
                ']' => {
                    self.idx += 1;
                    return Some(Json::Array(items));
                }
                _ => return None,
            }
        }
    }

    fn parse_string(&mut self) -> Option<String> {
        if self.peek()? != '"' {
            return None;
        }
        self.idx += 1;
        let mut out = String::new();
        loop {
            let c = self.peek()?;
            self.idx += 1;
            match c {
                '"' => return Some(out),
                '\\' => {
                    let esc = self.peek()?;
                    self.idx += 1;
                    match esc {
                        'n' => out.push('\n'),
                        'r' => out.push('\r'),
                        't' => out.push('\t'),
                        'b' => out.push('\u{08}'),
                        'f' => out.push('\u{0c}'),
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        '/' => out.push('/'),
                        'u' => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let h = self.peek()?;
                                self.idx += 1;
                                code = code * 16 + h.to_digit(16)?;
                            }
                            // handle surrogate pairs
                            if (0xd800..0xdc00).contains(&code) {
                                if self.peek()? == '\\' {
                                    self.idx += 1;
                                    if self.peek()? == 'u' {
                                        self.idx += 1;
                                        let mut low = 0u32;
                                        for _ in 0..4 {
                                            let h = self.peek()?;
                                            self.idx += 1;
                                            low = low * 16 + h.to_digit(16)?;
                                        }
                                        let combined = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
                                        out.push(char::from_u32(combined)?);
                                        continue;
                                    }
                                }
                                out.push('\u{fffd}');
                            } else {
                                out.push(char::from_u32(code)?);
                            }
                        }
                        _ => return None,
                    }
                }
                c => out.push(c),
            }
        }
    }

    fn parse_bool(&mut self) -> Option<Json> {
        let rest: String = self.chars[self.idx..].iter().take(5).collect();
        if rest.starts_with("true") {
            self.idx += 4;
            Some(Json::Bool(true))
        } else if rest.starts_with("false") {
            self.idx += 5;
            Some(Json::Bool(false))
        } else {
            None
        }
    }

    fn parse_null(&mut self) -> Option<Json> {
        let rest: String = self.chars[self.idx..].iter().take(4).collect();
        if rest.starts_with("null") {
            self.idx += 4;
            Some(Json::Null)
        } else {
            None
        }
    }

    fn parse_number(&mut self) -> Option<Json> {
        let start = self.idx;
        while self.idx < self.chars.len() {
            let c = self.chars[self.idx];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.idx += 1;
            } else {
                break;
            }
        }
        if start == self.idx {
            return None;
        }
        let text: String = self.chars[start..self.idx].iter().collect();
        text.parse::<f64>().ok().map(Json::Number)
    }
}

/// Remove the configuration file.
pub fn clear_config() -> std::io::Result<()> {
    let path = config_file().ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::NotFound, "no home directory")
    })?;
    std::fs::remove_file(&path)
}

