//! Terminal output helpers.
//!
//! Colours are written as raw ANSI sequences in the same order that the
//! `termcolor` crate emits them (a reset first, then the individual
//! attributes), and a reset is always written after the styled text.

use std::io::Write;

pub const RESET: &str = "\x1b[0m";
pub const BOLD: &str = "\x1b[1m";
pub const YELLOW: &str = "\x1b[33m";
pub const GREEN: &str = "\x1b[32m";
pub const RED: &str = "\x1b[31m";

fn stdout() -> std::io::StdoutLock<'static> {
    let out = std::io::stdout();
    out.lock()
}

/// Write `text` to stdout in the given style, followed by a reset.
fn styled(color: &str, bold: bool, text: &str) {
    let mut out = stdout();
    let _ = write!(out, "{}", RESET);
    if bold {
        let _ = write!(out, "{}", BOLD);
    }
    let _ = write!(out, "{}", color);
    let _ = write!(out, "{}", text);
    let _ = write!(out, "{}", RESET);
    let _ = out.flush();
}

/// Print a line of text in bold green (used for prompts and highlights).
pub fn bold_green(text: &str) {
    styled(GREEN, true, text);
}

/// Print a line of text in plain red (used for validation errors).
pub fn red(text: &str) {
    styled(RED, false, text);
}

/// Print a block of text in plain yellow.
pub fn yellow(text: &str) {
    styled(YELLOW, false, text);
}

/// The banner shown during first time setup.
pub const FIRST_TIME_SETUP_BANNER: &str = "############################################################\n\
####                  First Time Setup                  ####\n\
############################################################\n\
\n\
This tool requires you to have a repository with a README.md\n\
in the root folder. The markdown file is where your ideas\n\
will be stored.\n\
\n\
Once first time setup has completed, simply run Eureka again\n\
to begin writing down ideas.\n\
        \n";

/// Report an error the way eureka does: ` ERROR eureka > <message>`.
pub fn report_error(message: &str) {
    let err = std::io::stderr();
    let mut err = err.lock();
    let _ = writeln!(err, " ERROR eureka > {}", message);
    let _ = err.flush();
}

/// Read one line from stdin, returning the trimmed input.
///
/// An empty line (including a closed stdin) is reported back so the caller can
/// decide to ask again.
pub fn read_line_trimmed() -> Option<String> {
    let mut line = String::new();
    match std::io::stdin().read_line(&mut line) {
        Ok(0) => None,
        Ok(_) => Some(line.trim().to_string()),
        Err(_) => None,
    }
}

/// Ask the user for a value, repeating until a non-empty answer is given.
pub fn prompt_required(prompt: &str) -> String {
    loop {
        bold_green(&format!("{}\n", prompt));
        print_prompt_arrow();
        match read_line_trimmed() {
            Some(s) if !s.is_empty() => return s,
            _ => continue,
        }
    }
}

/// Ask for an absolute path, repeating until a usable answer is given.
pub fn prompt_absolute_path(prompt: &str) -> String {
    loop {
        bold_green(&format!("{}\n", prompt));
        print_prompt_arrow();
        let answer = match read_line_trimmed() {
            Some(s) => s,
            None => continue,
        };
        if answer.is_empty() {
            continue;
        }
        if !std::path::Path::new(&answer).is_absolute() {
            red("Path must be absolute\n");
            continue;
        }
        return answer;
    }
}

fn print_prompt_arrow() {
    let mut out = stdout();
    let _ = write!(out, "> ");
    let _ = out.flush();
}
