//! The configuration file lives in `$HOME/.config/eureka/config.json` and only
//! holds the path to the ideas repository.

use std::path::{Path, PathBuf};

/// Where the configuration is stored.
pub fn config_dir() -> Option<PathBuf> {
    home_dir().map(|h| h.join(".config").join("eureka"))
}

pub fn config_file() -> Option<PathBuf> {
    config_dir().map(|d| d.join("config.json"))
}

/// `$HOME`, falling back to the passwd database when it is unset or empty.
fn home_dir() -> Option<PathBuf> {
    if let Some(h) = std::env::var_os("HOME") {
        if !h.is_empty() {
            return Some(PathBuf::from(h));
        }
    }
    passwd_home()
}

#[repr(C)]
struct Passwd {
    pw_name: *const i8,
    pw_passwd: *const i8,
    pw_uid: u32,
    pw_gid: u32,
    pw_gecos: *const i8,
    pw_gecos2: *const i8,
    pw_dir: *const i8,
    pw_shell: *const i8,
}

extern "C" {
    fn getuid() -> u32;
    fn getpwuid_r(
        uid: u32,
        pwd: *mut Passwd,
        buf: *mut i8,
        buflen: usize,
        result: *mut *mut Passwd,
    ) -> i32;
    fn sysconf(name: i32) -> i64;
}

const _SC_GETPW_R_SIZE_MAX: i32 = 201;

/// Look the current user up in /etc/passwd to find their home directory.
fn passwd_home() -> Option<PathBuf> {
    let amount = unsafe { sysconf(_SC_GETPW_R_SIZE_MAX) };
    let amt = if amount < 0 { 512usize } else { amount as usize };
    let mut buf: Vec<i8> = Vec::with_capacity(amt);
    let mut pwd: Passwd = unsafe { std::mem::zeroed() };
    let mut result: *mut Passwd = std::ptr::null_mut();
    let uid = unsafe { getuid() };
    let rc = unsafe { getpwuid_r(uid, &mut pwd, buf.as_mut_ptr(), amt, &mut result) };
    if rc != 0 || result.is_null() || pwd.pw_dir.is_null() {
        return None;
    }
    let dir = unsafe { std::ffi::CStr::from_ptr(pwd.pw_dir) };
    let s = dir.to_bytes();
    if s.is_empty() {
        return None;
    }
    Some(PathBuf::from(std::os::unix::OsStr::from_bytes(s)))
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Config {
    pub repo: String,
}

impl Config {
    /// Read the configuration file.  Any failure (missing file, bad json,
    /// wrong types) results in `None`.
    pub fn load() -> Option<Config> {
        let path = config_file()?;
        let contents = std::fs::read_to_string(&path).ok()?;
        parse_config(&contents)
    }

    /// Store the configuration, creating the configuration directory first.
    pub fn save(&self) -> std::io::Result<()> {
        let dir = config_dir().ok_or_else(|| {
            std::io::Error::new(std::io::ErrorKind::NotFound, "no home directory")
        })?;
        std::fs::create_dir_all(&dir)?;
        let path = dir.join("config.json");
        std::fs::write(&path, json_for(&self.repo))
    }

    pub fn repo_path(&self) -> PathBuf {
        PathBuf::from(&self.repo)
    }
}

/// Serialize `{"repo": <path>}` exactly like the original tool does.
pub fn json_for(repo: &str) -> String {
    format!("{{\"repo\":{}}}", json_string(repo))
}

fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// A tiny json reader, good enough for the single-field configuration file.
fn parse_config(text: &str) -> Option<Config> {
    let mut lexer = Lexer::new(text);
    let value = lexer.parse_value()?;
    match value {
        Json::Object(fields) => {
            // duplicate keys make deserialization fail
            let mut repos: Vec<&Json> = fields.iter().filter(|(k, _)| *k == "repo").map(|(_, v)| v).collect();
            if repos.len() != 1 {
                return None;
            }
            match repos.pop()? {
                Json::String(s) => Some(Config { repo: s.clone() }),
                _ => None,
            }
        }
        _ => None,
    }
