enum Json {
    String(String),
    Number(f64),
    Bool(bool),
    Null,
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

struct Lexer<'a> {
    chars: Vec<char>,
    idx: usize,
    _marker: std::marker::PhantomData<&'a ()>,
}

impl<'a> Lexer<'a> {
    fn new(text: &'a str) -> Lexer<'a> {
        Lexer { chars: text.chars().collect(), idx: 0, _marker: std::marker::PhantomData }
    }

    fn skip_ws(&mut self) {
        while self.idx < self.chars.len() && self.chars[self.idx].is_whitespace() {
            self.idx += 1;
        }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.idx).copied()
    }

    fn parse_value(&mut self) -> Option<Json> {
        self.skip_ws();
        match self.peek()? {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string().map(Json::String),
            't' | 'f' => self.parse_bool(),
            'n' => self.parse_null(),
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Option<Json> {
        self.idx += 1;
        let mut fields: Vec<(String, Json)> = Vec::new();
        self.skip_ws();
        if self.peek()? == '}' {
            self.idx += 1;
            return Some(Json::Object(fields));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.peek()? != ':' {
                return None;
            }
            self.idx += 1;
            let value = self.parse_value()?;
            fields.push((key, value));
            self.skip_ws();
            match self.peek()? {
                ',' => {
                    self.idx += 1;
                }
                '}' => {
                    self.idx += 1;
                    return Some(Json::Object(fields));
                }
                _ => return None,
            }
        }
    }

    fn parse_array(&mut self) -> Option<Json> {
        self.idx += 1;
        let mut items: Vec<Json> = Vec::new();
        self.skip_ws();
        if self.peek()? == ']' {
            self.idx += 1;
            return Some(Json::Array(items));
        }
        loop {
            let v = self.parse_value()?;
            items.push(v);
            self.skip_ws();
            match self.peek()? {
                ',' => {
                    self.idx += 1;
                }
                ']' => {
                    self.idx += 1;
                    return Some(Json::Array(items));
                }
                _ => return None,
            }
        }
    }

    fn parse_string(&mut self) -> Option<String> {
        if self.peek()? != '"' {
            return None;
        }
        self.idx += 1;
        let mut out = String::new();
        loop {
            let c = self.peek()?;
            self.idx += 1;
            match c {
                '"' => return Some(out),
                '\\' => {
                    let esc = self.peek()?;
                    self.idx += 1;
                    match esc {
                        'n' => out.push('\n'),
                        'r' => out.push('\r'),
                        't' => out.push('\t'),
                        'b' => out.push('\u{08}'),
                        'f' => out.push('\u{0c}'),
                        '"' => out.push('"'),
                        '\\' => out.push('\\'),
                        '/' => out.push('/'),
                        'u' => {
                            let mut code = 0u32;
                            for _ in 0..4 {
                                let h = self.peek()?;
                                self.idx += 1;
                                code = code * 16 + h.to_digit(16)?;
                            }
                            // handle surrogate pairs
                            if (0xd800..0xdc00).contains(&code) {
                                if self.peek()? == '\\' {
                                    self.idx += 1;
                                    if self.peek()? == 'u' {
                                        self.idx += 1;
                                        let mut low = 0u32;
                                        for _ in 0..4 {
                                            let h = self.peek()?;
                                            self.idx += 1;
                                            low = low * 16 + h.to_digit(16)?;
                                        }
                                        let combined = 0x10000 + ((code - 0xd800) << 10) + (low - 0xdc00);
                                        out.push(char::from_u32(combined)?);
                                        continue;
                                    }
                                }
                                out.push('\u{fffd}');
                            } else {
                                out.push(char::from_u32(code)?);
                            }
                        }
                        _ => return None,
                    }
                }
                c => out.push(c),
            }
        }
    }

    fn parse_bool(&mut self) -> Option<Json> {
        let rest: String = self.chars[self.idx..].iter().take(5).collect();
        if rest.starts_with("true") {
            self.idx += 4;
            Some(Json::Bool(true))
        } else if rest.starts_with("false") {
            self.idx += 5;
            Some(Json::Bool(false))
        } else {
            None
        }
    }

    fn parse_null(&mut self) -> Option<Json> {
        let rest: String = self.chars[self.idx..].iter().take(4).collect();
        if rest.starts_with("null") {
            self.idx += 4;
            Some(Json::Null)
        } else {
            None
        }
    }

    fn parse_number(&mut self) -> Option<Json> {
        let start = self.idx;
        while self.idx < self.chars.len() {
            let c = self.chars[self.idx];
            if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' || c == 'e' || c == 'E' {
                self.idx += 1;
            } else {
                break;
            }
        }
        if start == self.idx {
            return None;
        }
        let text: String = self.chars[start..self.idx].iter().collect();
        text.parse::<f64>().ok().map(Json::Number)
    }
}

/// Remove the configuration file.
pub fn clear_config() -> std::io::Result<()> {
