#[derive(Debug, Default, Clone)]
pub struct Args {
    pub clear_config: bool,
    pub view: bool,
}

/// What the command line asked the program to do.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Invocation {
    /// print the help text and exit successfully
    Help,
    /// print the version and exit successfully
    Version,
    /// carry on with the requested action
    Run(Args),
}

/// A failure while parsing the command line; rendered like clap's errors.
pub struct UsageError {
    pub message: String,
    pub usage: String,
}

impl UsageError {
    fn new(message: String, usage: String) -> UsageError {
        UsageError { message, usage }
    }
}

impl std::fmt::Display for UsageError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}\n\n{}\n\nFor more information, try '--help'.", self.message, self.usage)
    }
}

/// The name of the binary, taken from `argv[0]` and falling back to the crate
/// name when it cannot be determined.
pub fn bin_name() -> String {
    match std::env::args_os().next() {
        Some(arg0) => match Path::new(&arg0).file_name() {
            Some(name) => name.to_string_lossy().into_owned(),
            None => NAME.to_string(),
        },
        None => NAME.to_string(),
    }
}

fn usage_options(bin: &str) -> String {
    format!("Usage: {} [OPTIONS]", bin)
}

fn usage_arg(bin: &str, arg: &str) -> String {
    format!("Usage: {} {}", bin, arg)
}

/// The long flags, in the order they are declared.
const LONGS: [&str; 4] = ["clear-config", "view", "help", "version"];

/// Print the help text.
pub fn help_text(bin: &str) -> String {
    format!(
        "{}\n\n{}\n\nOptions:\n      --clear-config  Clear your stored configuration\n  -v, --view          View ideas with your $PAGER env variable. If unset use less\n  -h, --help          Print help\n  -V, --version       Print version\n",
        HELP_ENTRY,
        usage_options(bin)
    )
}

/// Print the version string.
pub fn version_text() -> String {
    format!("{} {}\n", NAME, VERSION)
}

/// Jaro similarity, as implemented by the `strsim` crate.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    if a.is_empty() && b.is_empty() {
        return 1.0;
    }
    if a.is_empty() || b.is_empty() {
        return 0.0;
    }
    let a_len = a.len();
    let b_len = b.len();
    if a_len == 1 && b_len == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;

    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (i + search_range + 1).min(b_len);
        if min_bound >= max_bound {
            continue;
        }
        for (j, b_elem) in b.iter().enumerate() {
            if min_bound <= j && j < max_bound && a_elem == b_elem && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }

    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / a_len as f64)
                + (matches / b_len as f64)
                + ((matches - transpositions) / matches))
    }
}

/// Jaro-Winkler similarity with the unbounded prefix boost used by `strsim`.
fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a
        .chars()
        .zip(b.chars())
        .take_while(|(a_elem, b_elem)| a_elem == b_elem)
        .count();
    let result = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if result <= 1.0 {
        result
    } else {
        1.0
    }
}

/// Pick the closest matching long flag, if any is close enough.
fn did_you_mean(arg: &str) -> Option<String> {
    let mut candidates: Vec<(f64, String)> = LONGS
        .iter()
        .map(|pv| (jaro_winkler(arg, pv), pv.to_string()))
        .filter(|(confidence, _)| *confidence > 0.7)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.reverse();
    candidates.into_iter().next().map(|(_, pv)| pv)
