fn find_editor() -> Option<PathBuf> {
    match std::env::var_os("EDITOR") {
        Some(ed) => Some(PathBuf::from(ed)),
        None => resolve_binary("vi"),
    }
}

/// Make sure we are on the `main` branch, then commit the idea file.
fn store_idea(repo: &git::Repository, readme: &Path, summary: &str) -> git::Result<()> {
    switch_to_main(repo)?;

    let name = repo.config_string("user.name")?;
    let email = repo.config_string("user.email")?;
    let author = repo.signature_now(&name, &email)?;
    let committer = repo.signature_now(&name, &email)?;

    let mut index = repo.index()?;
    index.add_path("README.md")?;
    index.write()?;
    let tree_id = index.write_tree_to()?;
    let tree = git::Tree { raw: unsafe { tree_from_id(repo, &tree_id)? } };

    repo.commit(Some("HEAD"), &author, &committer, summary, tree.raw)?;
    Ok(())
}

fn tree_from_id(repo: &git::Repository, id: &git::GitOid) -> git::Result<*mut git::git_tree> {
    let commit = {
        let mut raw: *mut git::git_commit = std::ptr::null_mut();
        let rc = unsafe { git::git_commit_lookup(&mut raw, repo.raw(), id as *const git::GitOid) };
        if rc < 0 {
            return Err(git::last_error(rc));
        }
        raw
    };
    let mut tree: *mut git::git_tree = std::ptr::null_mut();
    let rc = unsafe { git::git_commit_tree_lookup(&mut tree, commit) };
    if rc < 0 {
        return Err(git::last_error(rc));
    }
    Ok(tree)
}

/// Ensure the `main` branch exists, point the working tree at it and move HEAD.
fn switch_to_main(repo: &git::Repository) -> git::Result<()> {
    let head = repo.reference_lookup("HEAD", true)?;
    let head_commit = head.peel_to_commit()?;

    let main_exists = repo.branch_lookup("main", false).is_ok();
    if !main_exists {
        repo.branch_create("main", &head_commit.id, false)?;
    }

    let main_branch = repo.branch_lookup("main", false)?;
    let main_commit = main_branch.peel_to_commit()?;
    repo.checkout_tree(unsafe { main_commit.raw() as *const git::git_object }, git::GIT_CHECKOUT_SAFE)?;
    repo.set_head("refs/heads/main")?;
    Ok(())
}

/// Push the `main` branch to `origin`.
fn push(repo: &git::Repository) -> git::Result<()> {
    let mut remote = repo.find_remote("origin")?;
    remote.push(&["refs/heads/main:refs/heads/main"])
}
